function parseDatasetExercises(data:unknown):Exercise[]{
 if(!Array.isArray(data))return [];
 return data.filter(item=>item&&typeof item.name==='string').map(item=>({id:String(item.id),name:item.name,category:String(item.category??item.body_part??''),target:String(item.target??''),equipment:String(item.equipment??''),media_id:String(item.media_id??''),image:typeof item.image==='string'?item.image:undefined,gif_url:typeof item.gif_url==='string'?item.gif_url:undefined,instructions:item.instructions,instruction_steps:item.instruction_steps}));
}
async function fetchExerciseCatalog():Promise<Exercise[]>{const response=await fetch('https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/data/exercises.json');if(!response.ok)throw new Error('Exercise catalog unavailable');return parseDatasetExercises(await response.json());}
const normalizeExerciseName=(name:string)=>name.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function findCatalogExercise(name:string,catalog:Exercise[]):Exercise|undefined{
 const normalized=normalizeExerciseName(name);if(!normalized)return undefined;
 const exact=catalog.find(exercise=>normalizeExerciseName(exercise.name)===normalized);if(exact)return exact;
 const contained=catalog.filter(exercise=>{const candidate=normalizeExerciseName(exercise.name);return candidate.includes(normalized)||normalized.includes(candidate);}).sort((a,b)=>Math.abs(normalizeExerciseName(a.name).length-normalized.length)-Math.abs(normalizeExerciseName(b.name).length-normalized.length));
 if(contained[0])return contained[0];
 const words=new Set(normalized.split(' ').filter(word=>word.length>2));let best:Exercise|undefined;let bestScore=0;
 for(const exercise of catalog){const candidateWords=new Set(normalizeExerciseName(exercise.name).split(' ').filter(word=>word.length>2));if(!candidateWords.size)continue;const overlap=[...words].filter(word=>candidateWords.has(word)).length;const score=overlap/Math.max(words.size,candidateWords.size);if(score>bestScore){bestScore=score;best=exercise;}}
 return bestScore>=0.65?best:undefined;
}
function addCatalogMedia(sessions:Session[],catalog:Exercise[]):Session[]{return sessions.map(session=>({...session,moves:session.moves.map(move=>{const exercise=findCatalogExercise(move.name,catalog);return exercise?{...move,image:move.image??exercise.image,gif_url:move.gif_url??exercise.gif_url,target:move.target??exercise.target,equipment:move.equipment??exercise.equipment,instructions:move.instructions??exercise.instructions,instruction_steps:move.instruction_steps??exercise.instruction_steps}:move;})}));}
